FuncDef.Code:
vec2 uvWrapMirror(vec2 uv)
{
    return abs(mod(uv - 1.0, 2.0) - 1.0);
}

//-------------------------------------------------------------------------------
// main
//-------------------------------------------------------------------------------
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = convertFragCoordsToUv(fragCoord);

    int numSamples = renderer_numSamples;//24;
    float angleStep = 2.0 * PI / numSamples;
    float angle = 0.0;

    vec4 col = vec4(0.0);
    for(int i=0; i<numSamples; i++)
    {
        angle = i * angleStep;
        vec2 uvOffset = 0.01 * renderer_blurRadius * vec2(cos(angle), sin(angle));

        vec2 uvToTest = uv + uvOffset;

        // Mirrored sampling helps reduce visible artifacts at the edges of the screen
        uvToTest = uvWrapMirror(uvToTest);

        col += texture(iChannel1, uvToTest);
    }

    col.rgb /= numSamples;
    col.a = 1.0;

    fragColor = col;
}
